def power(base, exp):
    # Handles standard integer exponentiation, including cases where 
    # the result might not be an integer if exp is negative and base != +/- 1.
    # Since P must be a positive prime integer, we only care if the result is a positive integer.
    if exp >= 0:
        return base ** exp

    # If exp < 0, we check if the base is +/- 1 for the result to be an integer.
    if base == 1:
        return 1
    if base == -1:
        return (-1) ** exp # This will be +/- 1

    # If base is not 1 or -1, a negative integer exponent yields a fraction, 
    # which cannot be a positive prime integer.
    return None 

def calculate_P(x, y, z):
    try:
        # Check for potential issues with non-integer intermediate results
        y_x = power(y, x)
        z_y = power(z, y)
        x_z = power(x, z)

        if y_x is None or z_y is None or x_z is None:
            return None # Not an integer result

        P = y_x * z_y * x_z
        return P
    except OverflowError:
        # P is too large to check easily, assume non-prime for practical purposes in this search
        return None

def search_triples():
    # Max |x|, |y|, |z| such that x^2+y^2+z^2 <= 51
    # Max possible value is 7 (7^2 = 49).
    limit = 7

    solutions = []

    # Iterate over all non-zero integers in the range [-limit, limit]
    for x in range(-limit, limit + 1):
        if x == 0: continue
        for y in range(-limit, limit + 1):
            if y == 0: continue
            for z in range(-limit, limit + 1):
                if z == 0: continue

                S = x**2 + y**2 + z**2
                if S > 51:
                    continue

                P = calculate_P(x, y, z)

                if P is not None and P > 0 and is_prime(P):
                    solutions.append((S, x, y, z))

    # Sort by S, then by (x, y, z) lexicographically for consistent ordering
    solutions.sort()
    return solutions

